import { readFileSync } from 'node:fs';
import { describe, it, expect } from 'vitest';
import { lightNormalizeCode } from '../src/standards/light-normalize.js';
import { splitReplacesParts } from '../src/standards/repository.js';

// Light normalization is THE merge key (user decision 2026-11-23).
// The shared fixture is generated by tests/fixtures/generate-shared.ts
// and is also tested in Reverse_proxy — elib is the source of truth.

interface SharedCase {
  input: string;
  year_field: number | null;
  normalized_code: string | null;
  base_key: string | null;
  year: number | null;
  is_amendment: boolean | null;
  needs_review: boolean | null;
}

const shared = JSON.parse(
  readFileSync(new URL('./fixtures/code-normalize-shared.json', import.meta.url), 'utf8')
) as SharedCase[];

describe('lightNormalizeCode — fixture khóa dùng chung hai repo', () => {
  it(`khớp ${shared.length} case (input + year_field -> khóa)`, () => {
    const mismatches: string[] = [];
    for (const c of shared) {
      const light = lightNormalizeCode(c.input, c.year_field);
      const got = {
        normalized_code: light?.normalized_code ?? null,
        base_key: light?.base_key ?? null,
        year: light?.year ?? null,
        is_amendment: light?.is_amendment ?? null,
        needs_review: light?.needs_review ?? null
      };
      const want = {
        normalized_code: c.normalized_code,
        base_key: c.base_key,
        year: c.year,
        is_amendment: c.is_amendment,
        needs_review: c.needs_review
      };
      if (JSON.stringify(got) !== JSON.stringify(want)) {
        mismatches.push(
          `${JSON.stringify(c.input)} (year_field=${c.year_field}): want ${JSON.stringify(want)} got ${JSON.stringify(got)}`
        );
      }
    }
    expect(mismatches).toEqual([]);
  });
});

describe('lightNormalizeCode — quy tắc "/"', () => {
  it('bỏ "/" khi hai bên là chữ cái: ISO/TS = ISO TS, TCVN/ISO = TCVN ISO', () => {
    const withSlash = lightNormalizeCode('TCVN ISO/TS 16949:2011');
    const withSpace = lightNormalizeCode('TCVN ISO TS 16949:2011');
    expect(withSlash?.normalized_code).toBe('TCVNISOTS16949:2011');
    expect(withSlash?.normalized_code).toBe(withSpace?.normalized_code);

    expect(lightNormalizeCode('TCVN ISO TS 9002:2017')?.normalized_code).toBe(
      'TCVNISOTS9002:2017'
    );
    expect(lightNormalizeCode('TCVN/ISO 9001:2015')?.normalized_code).toBe(
      lightNormalizeCode('TCVN ISO 9001:2015')?.normalized_code
    );
    expect(lightNormalizeCode('TCVN/ISO 9001:2015')?.normalized_code).toBe('TCVNISO9001:2015');
  });

  it('giữ "/" khi sau chữ số (hậu tố /BXD, /Amd 1, /AC)', () => {
    expect(lightNormalizeCode('QCVN 02:2016/BXD')?.normalized_code).toBe('QCVN02:2016/BXD');
    const amended = lightNormalizeCode('ISO 9001:2015/Amd 1:2016');
    expect(amended?.normalized_code).toBe('ISO9001:2015/AMD1:2016');
    expect(amended?.is_amendment).toBe(true);
    expect(amended?.year).toBe(2015);
    expect(amended?.base_key).toBe('ISO9001');
    expect(lightNormalizeCode('ISO 9001:2015/AC:2019')?.normalized_code).toBe(
      'ISO9001:2015/AC:2019'
    );
  });

  it('ISO/FDIS là designation riêng, không gộp vào ISO', () => {
    expect(lightNormalizeCode('ISO/FDIS 9001', 2015)?.normalized_code).toBe('ISOFDIS9001:2015');
    expect(lightNormalizeCode('ISO/FDIS 9001', 2015)?.normalized_code).not.toBe(
      lightNormalizeCode('ISO 9001', 2015)?.normalized_code
    );
  });
});

describe('lightNormalizeCode — năm', () => {
  it('cùng tiêu chuẩn từ QT (code không năm + year field) và nguồn viết kèm năm -> cùng khóa', () => {
    const fromQt = lightNormalizeCode('ISO 9001', 2015);
    const yeared = lightNormalizeCode('ISO 9001:2015');
    expect(fromQt?.normalized_code).toBe('ISO9001:2015');
    expect(fromQt?.normalized_code).toBe(yeared?.normalized_code);
    expect(fromQt?.base_key).toBe('ISO9001');
    expect(fromQt?.year).toBe(2015);
    expect(fromQt?.needs_review).toBe(false);
  });

  it('code có ":YYYY" khác trường year -> giữ khóa theo code + needs_review', () => {
    const light = lightNormalizeCode('TCVN 9143:2022', 2020);
    expect(light?.normalized_code).toBe('TCVN9143:2022');
    expect(light?.year).toBe(2022);
    expect(light?.needs_review).toBe(true);
  });

  it('năm hai chữ số giữ nguyên, không suy ra 1988', () => {
    const light = lightNormalizeCode('14 TCN 58-88');
    expect(light?.normalized_code).toBe('14TCN58-88');
    expect(light?.year).toBeNull();
    expect(light?.base_key).toBe('14TCN58-88');
  });

  it('mã không năm + không year field -> khóa không năm (normativeReference)', () => {
    const light = lightNormalizeCode('TCVN 4253');
    expect(light?.normalized_code).toBe('TCVN4253');
    expect(light?.base_key).toBe('TCVN4253');
    expect(light?.year).toBeNull();
  });

  it('amendment không có ":năm" + có year field -> không thêm ":year", needs_review', () => {
    const light = lightNormalizeCode('ISO 9001/Amd 1', 2016);
    expect(light?.normalized_code).toBe('ISO9001/AMD1');
    expect(light?.is_amendment).toBe(true);
    expect(light?.needs_review).toBe(true);
    expect(light?.year).toBe(2016);
  });

  it('is_amendment qua regex /AMD /COR /AC +A\\d', () => {
    expect(lightNormalizeCode('EN 1994-1-1:2004/Amd 1:2010')?.is_amendment).toBe(true);
    expect(lightNormalizeCode('ISO 9001:2015/Cor 1:2019')?.is_amendment).toBe(true);
    expect(lightNormalizeCode('EN 1090-2:2018+A1:2020')?.is_amendment).toBe(true);
    expect(lightNormalizeCode('TCVN 9143:2022')?.is_amendment).toBe(false);
  });
});

describe('lightNormalizeCode — mã rác / không chuẩn hóa được', () => {
  it('rỗng, khoảng trắng, ký tự lạ, chỉ chữ cái (không có số) -> null', () => {
    expect(lightNormalizeCode('')).toBeNull();
    expect(lightNormalizeCode('   ')).toBeNull();
    expect(lightNormalizeCode('???')).toBeNull();
    // Quy tắc đã chốt trong code: mã tiêu chuẩn luôn có số; chuỗi chỉ
    // gồm chữ cái không phải mã.
    expect(lightNormalizeCode('abc')).toBeNull();
    expect(lightNormalizeCode('TCVN')).toBeNull();
  });

  it('bỏ dấu tiếng Việt + viết hoa + bỏ khoảng trắng/xuống dòng', () => {
    expect(lightNormalizeCode('TCĐBVN 01:2020')?.normalized_code).toBe('TCDBVN01:2020');
    expect(lightNormalizeCode('tcvn 9143:2022')?.normalized_code).toBe('TCVN9143:2022');
    expect(lightNormalizeCode('TCVN\n9143:2022')?.normalized_code).toBe('TCVN9143:2022');
  });
});

describe('splitReplacesParts — replaces của TCVN_QT (mẫu ISO 9001 thật)', () => {
  it('tách "*", lấy năm từ "(YYYY-MM)", corrigendum văn xuôi đánh dấu rawOnly', () => {
    const parts = splitReplacesParts(
      'ISO 9001 (2008-11)*ISO/FDIS 9001 (2015-07)*ISO 9001 Technical Corrigendum 1 (2009-07)'
    );
    expect(parts).toEqual([
      { code: 'ISO 9001', year: 2008, raw: 'ISO 9001 (2008-11)', rawOnly: false },
      { code: 'ISO/FDIS 9001', year: 2015, raw: 'ISO/FDIS 9001 (2015-07)', rawOnly: false },
      {
        code: 'ISO 9001 Technical Corrigendum 1',
        year: 2009,
        raw: 'ISO 9001 Technical Corrigendum 1 (2009-07)',
        rawOnly: true
      }
    ]);
    // Khóa đích tương ứng:
    expect(lightNormalizeCode(parts[0].code, parts[0].year)?.normalized_code).toBe('ISO9001:2008');
    expect(lightNormalizeCode(parts[1].code, parts[1].year)?.normalized_code).toBe(
      'ISOFDIS9001:2015'
    );
  });
});
